import {readFileSync,writeFileSync} from 'node:fs';
import {originalRoomSlots} from './lib/original-room-slots.mjs';
const {limit,slots}=originalRoomSlots();
const lines=[
  '-- Generated by scripts/generate-original-room-provisioning.mjs.',
  '-- Exact captured room-1 schema copies, covering the original configured',
  `-- ${limit} possible room slots (base limit plus unique perpetual room types).`,
  '-- Install before enabling the complete engine. No player rows are copied.',
  "do $$begin if exists(select from dtr_runtime.original_control where enabled) then raise exception 'disable original engine before room schema provisioning';end if;end$$;"
];
for(const slot of slots){
  const key=/"([^"]+)" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY/.exec(slot.sql)?.[1];
  if(!key)throw new Error('Original room identity is missing: '+slot.name);
  lines.push(slot.sql,
    `alter table public."${slot.name}" enable row level security;`,
    `revoke all on public."${slot.name}" from public,anon,authenticated,service_role;`,
    `insert into dtr_runtime.original_tables(table_name,primary_key,identity_column) values('${slot.name}','${key}',true) on conflict(table_name) do nothing;`);
}
const text=lines.join('\n')+'\n',path='supabase/migrations/20261102183000_original_room_slots.sql';
if(process.argv.includes('--check')){if(readFileSync(path,'utf8')!==text)throw new Error('Original room provisioning is stale.');}
else writeFileSync(path,text);
console.log({originalRoomLimit:limit,additionalTables:slots.length});
